const LOGO_SRC = "data:image/png;base64,";

const userData = {
  name: "Jagadeesh Jaladani",
  referralCode: "JAGA2026",
  friendsReferred: 12,
  pointsEarned: 240,
  creditsEarned: 120
};

const leaderboardData = [
  { name: "Rahul Sharma",       referred: 31, points: 620 },
  { name: "Priya Verma",        referred: 27, points: 540 },
  { name: "Arjun Singh",        referred: 22, points: 440 },
  { name: "Neha Gupta",         referred: 18, points: 360 },
  { name: "Jagadeesh Jaladani", referred: 12, points: 240 }
];

function setReferralLink() {
  const link = `https://gotoshop.com/join?ref=${userData.referralCode}`;
  document.getElementById("referral-link").value = link;
  document.getElementById("whatsapp-btn").href =
    `https://wa.me/?text=Hey!%20Join%20Gotoshop%20-%20India's%20cheapest%20shopping%20platform!%20Use%20my%20referral%20link%20and%20we%20both%20earn%20rewards!%20${encodeURIComponent(link)}`;
  document.getElementById("email-btn").href =
    `mailto:?subject=Join%20Gotoshop%20%26%20Earn%20Rewards!&body=Hey!%0A%0AJoin%20Gotoshop%20-%20India's%20Online%20Shopping%20Destination!%0AUse%20my%20referral%20link%3A%0A%0A${encodeURIComponent(link)}%0A%0AGotoshop%20%E2%80%94%20Cheap%20%C2%B7%20Fast%20%C2%B7%20Vast`;
}

function copyLink() {
  const linkInput = document.getElementById("referral-link");
  const copyBtn   = document.getElementById("copy-btn");
  const btnText   = document.getElementById("btn-text");
  const copyMsg   = document.getElementById("copy-msg");
  navigator.clipboard.writeText(linkInput.value).then(() => {
    btnText.textContent = "Copied!";
    copyBtn.classList.add("copied");
    copyMsg.classList.add("show");
    setTimeout(() => {
      btnText.textContent = "Copy Link";
      copyBtn.classList.remove("copied");
      copyMsg.classList.remove("show");
    }, 2500);
  });
}

function animateCount(elementId, target, prefix = "", suffix = "") {
  const el = document.getElementById(elementId);
  const start = performance.now();
  function update(now) {
    const progress = Math.min((now - start) / 1500, 1);
    const ease = 1 - Math.pow(1 - progress, 3);
    el.textContent = prefix + Math.floor(ease * target) + suffix;
    if (progress < 1) requestAnimationFrame(update);
    else el.textContent = prefix + target + suffix;
  }
  requestAnimationFrame(update);
}

function loadLeaderboard() {
  const body   = document.getElementById("leaderboard-body");
  const medals = ["🥇", "🥈", "🥉"];
  leaderboardData.forEach((user, i) => {
    const isMe = user.name === userData.name;
    const row  = document.createElement("div");
    row.className = "lb-row" + (isMe ? " me" : "");
    row.style.animationDelay = (i * 0.08) + "s";
    row.innerHTML = `
      <div class="lb-rank">${i < 3 ? medals[i] + " " + (i + 1) : (i + 1)}</div>
      <div class="lb-name">${user.name}${isMe ? '<span class="you-tag">You</span>' : ""}</div>
      <div class="lb-referred">${user.referred} friends</div>
      <div class="lb-points">${user.points} pts</div>
    `;
    body.appendChild(row);
  });
}

window.onload = function () {
  document.querySelectorAll("#site-logo, #footer-logo").forEach(img => {
    img.src = LOGO_SRC;
  });
  setReferralLink();
  setTimeout(() => {
    animateCount("friends-count", userData.friendsReferred);
    animateCount("points-earned", userData.pointsEarned);
    animateCount("credits-earned", userData.creditsEarned, "₹");
  }, 300);
  loadLeaderboard();
};